     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import { EncryptionService } from "modules/encryption/service/EncryptionService";
     4→import { VerificationService } from "modules/verification/service/VerificationService";
     5→import { type FC, useEffect, useState } from "react";
     6→import { ActivityIndicator, Image } from "react-native";
     7→import { Button, ScreenLayout } from "shared/components";
     8→import { Colors, TextSize } from "shared/styles";
     9→
    10→export const ConfirmIdentity: FC<
    11→  NativeStackScreenProps<Routes, "confirmIdentity">
    12→> = ({ navigation }) => {
    13→  const [loading, setLoading] = useState(true);
    14→  const [hasOtherDevices, setHasOtherDevices] = useState(false);
    15→  const [recoveryEnabled, setRecoveryEnabled] = useState(false);
    16→
    17→  useEffect(() => {
    18→    const checkSituation = async () => {
    19→      try {
    20→        const [otherDevices, recovery] = await Promise.all([
    21→          VerificationService.hasDevicesToVerifyAgainst(),
    22→          EncryptionService.isRecoveryEnabled(),
    23→        ]);
    24→        setHasOtherDevices(otherDevices);
    25→        setRecoveryEnabled(recovery);
    26→      } catch (error) {
    27→        console.error("Failed to check verification situation:", error);
    28→      } finally {
    29→        setLoading(false);
    30→      }
    31→    };
    32→    checkSituation();
    33→  }, []);
    34→
    35→  return (
    36→    <ScreenLayout>
    37→      <Block flex={1}>
    38→        <Block flex={1} justify="center" align="center" gap={24}>
    39→          <Block gap={12}>
    40→            <Text
    41→              size={TextSize.large}
    42→              textAlign="center"
    43→              font="InstrumentSans-Medium"
    44→            >
    45→              Verify your device
    46→            </Text>
    47→            <Text
    48→              textAlign="center"
    49→              font="InstrumentSans-Regular"
    50→              color={Colors.white50}
    51→            >
    52→              Verify this device to access your encrypted message history and
    53→              set up secure messaging.
    54→            </Text>
    55→          </Block>
    56→
    57→          <Block
    58→            border={{ borderRadius: 12 }}
    59→            background={Colors.white5}
    60→            paddings={[16, 16]}
    61→            gap={12}
    62→          >
    63→            <Block flexDirection="row" align="center" gap={12}>
    64→              <Image
    65→                source={require("assets/icons/info.png")}
    66→                tintColor={Colors.primary}
    67→                width={20}
    68→                height={20}
    69→              />
    70→              <Text color={Colors.white80} size={TextSize.small}>
    71→                Without verification, you won't be able to access messages sent
    72→                before this login.
    73→              </Text>
    74→            </Block>
    75→          </Block>
    76→        </Block>
    77→
    78→        {loading ? (
    79→          <Block align="center" paddings={[20, 0]}>
    80→            <ActivityIndicator color={Colors.primary} />
    81→          </Block>
    82→        ) : (
    83→          <Block gap={12} paddings={[0, 52]}>
    84→            {hasOtherDevices && (
    85→              <Button.Primary
    86→                onPress={() => navigation.navigate("verifyWithDevice")}
    87→              >
    88→                Verify with another device
    89→              </Button.Primary>
    90→            )}
    91→            {recoveryEnabled && (
    92→              <Button.Outline
    93→                onPress={() => navigation.navigate("enterRecoveryKey")}
    94→              >
    95→                Use recovery key
    96→              </Button.Outline>
    97→            )}
    98→            <Button.Outline onPress={() => navigation.navigate("cantConfirm")}>
    99→              Can't confirm identity?
   100→            </Button.Outline>
   101→          </Block>
   102→        )}
   103→      </Block>
   104→    </ScreenLayout>
   105→  );
   106→};
   107→

