     1→import {
     2→  type SessionVerificationControllerDelegate,
     3→  type SessionVerificationControllerInterface,
     4→  type SessionVerificationData,
     5→  SessionVerificationData_Tags,
     6→  type SessionVerificationRequestDetails,
     7→  VerificationState,
     8→} from "@unomed/react-native-matrix-sdk";
     9→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    10→
    11→type VerificationRequestCallback = (
    12→  details: SessionVerificationRequestDetails,
    13→) => void;
    14→
    15→type VerificationEmojisCallback = (
    16→  emojis: Array<{ symbol: string; description: string }>,
    17→) => void;
    18→
    19→type VerificationStateChangeCallback = (
    20→  state:
    21→    | "request"
    22→    | "accepted"
    23→    | "emojis"
    24→    | "success"
    25→    | "failed"
    26→    | "cancelled"
    27→    | "sasStarted",
    28→) => void;
    29→
    30→export type { VerificationRequestCallback, VerificationEmojisCallback, VerificationStateChangeCallback };
    31→
    32→export class VerificationService {
    33→  private static verificationController: SessionVerificationControllerInterface | null =
    34→    null;
    35→
    36→  private static onVerificationRequest: VerificationRequestCallback | null = null;
    37→  private static onVerificationEmojis: VerificationEmojisCallback | null = null;
    38→  private static onVerificationStateChange: VerificationStateChangeCallback | null =
    39→    null;
    40→
    41→  public static getVerificationState = () => {
    42→    return MatrixCore.getClient().encryption().verificationState();
    43→  };
    44→
    45→  public static isDeviceVerified = () => {
    46→    if (!MatrixCore.instance) return false;
    47→    return (
    48→      MatrixCore.instance.encryption().verificationState() ===
    49→      VerificationState.Verified
    50→    );
    51→  };
    52→
    53→  public static getDeviceId = () => {
    54→    if (!MatrixCore.instance) return null;
    55→    return MatrixCore.instance.session()?.deviceId || null;
    56→  };
    57→
    58→  public static getVerificationDetails = async () => {
    59→    const client = MatrixCore.getClient();
    60→    const userId = client.userId();
    61→    if (!userId) throw new Error("User ID not found");
    62→
    63→    const encryption = client.encryption();
    64→    const userIdentity = await encryption.userIdentity(userId, true);
    65→
    66→    return {
    67→      verificationState: encryption.verificationState(),
    68→      isVerified: VerificationService.isDeviceVerified(),
    69→      deviceId: VerificationService.getDeviceId(),
    70→      userIdentity: userIdentity
    71→        ? {
    72→            isVerified: userIdentity.isVerified(),
    73→            hasVerificationViolation: userIdentity.hasVerificationViolation(),
    74→            masterKey: userIdentity.masterKey(),
    75→          }
    76→        : null,
    77→    };
    78→  };
    79→
    80→  public static setupVerification = async (
    81→    onRequest: VerificationRequestCallback,
    82→    onEmojis: VerificationEmojisCallback,
    83→    onStateChange: VerificationStateChangeCallback,
    84→  ) => {
    85→    const client = MatrixCore.getClient();
    86→
    87→    VerificationService.onVerificationRequest = onRequest;
    88→    VerificationService.onVerificationEmojis = onEmojis;
    89→    VerificationService.onVerificationStateChange = onStateChange;
    90→
    91→    VerificationService.verificationController =
    92→      await client.getSessionVerificationController();
    93→
    94→    const delegate: SessionVerificationControllerDelegate = {
    95→      didReceiveVerificationRequest: (details: SessionVerificationRequestDetails) => {
    96→        console.log("📩 Verification request received:", details);
    97→        VerificationService.onVerificationStateChange?.("request");
    98→        VerificationService.onVerificationRequest?.(details);
    99→      },
   100→
   101→      didAcceptVerificationRequest: () => {
   102→        console.log("✅ Verification request accepted");
   103→        VerificationService.onVerificationStateChange?.("accepted");
   104→      },
   105→
   106→      didStartSasVerification: () => {
   107→        console.log("🔐 SAS verification started");
   108→        VerificationService.onVerificationStateChange?.("sasStarted");
   109→      },
   110→
   111→      didReceiveVerificationData: (data: SessionVerificationData) => {
   112→        console.log("📊 Verification data received:", data);
   113→
   114→        if (data.tag === SessionVerificationData_Tags.Emojis) {
   115→          const emojis = data.inner.emojis.map((emoji) => ({
   116→            symbol: emoji.symbol(),
   117→            description: emoji.description(),
   118→          }));
   119→          console.log("🎭 Emojis:", emojis);
   120→          VerificationService.onVerificationStateChange?.("emojis");
   121→          VerificationService.onVerificationEmojis?.(emojis);
   122→        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
   123→          console.log("🔢 Decimals:", data.inner.values);
   124→        }
   125→      },
   126→
   127→      didFail: () => {
   128→        console.log("❌ Verification failed");
   129→        VerificationService.onVerificationStateChange?.("failed");
   130→      },
   131→
   132→      didCancel: () => {
   133→        console.log("🚫 Verification cancelled");
   134→        VerificationService.onVerificationStateChange?.("cancelled");
   135→      },
   136→
   137→      didFinish: () => {
   138→        console.log("🎉 Verification finished successfully!");
   139→        VerificationService.onVerificationStateChange?.("success");
   140→      },
   141→    };
   142→
   143→    VerificationService.verificationController.setDelegate(delegate);
   144→    console.log("✅ Verification controller set up successfully");
   145→  };
   146→
   147→  public static acknowledgeVerification = async (
   148→    senderId: string,
   149→    flowId: string,
   150→  ) => {
   151→    if (!VerificationService.verificationController) {
   152→      throw new Error("Verification controller not initialized");
   153→    }
   154→    await VerificationService.verificationController.acknowledgeVerificationRequest(
   155→      senderId,
   156→      flowId,
   157→    );
   158→    console.log("✅ Verification request acknowledged");
   159→  };
   160→
   161→  public static acceptVerification = async () => {
   162→    if (!VerificationService.verificationController) {
   163→      throw new Error("Verification controller not initialized");
   164→    }
   165→    await VerificationService.verificationController.acceptVerificationRequest();
   166→    await VerificationService.verificationController.startSasVerification();
   167→    console.log("✅ Verification accepted and SAS started");
   168→  };
   169→
   170→  public static acceptVerificationRequest = async () => {
   171→    if (!VerificationService.verificationController) {
   172→      throw new Error("Verification controller not initialized");
   173→    }
   174→    await VerificationService.verificationController.acceptVerificationRequest();
   175→    console.log("✅ Verification request accepted");
   176→  };
   177→
   178→  public static approveVerification = async () => {
   179→    if (!VerificationService.verificationController) {
   180→      throw new Error("Verification controller not initialized");
   181→    }
   182→    await VerificationService.verificationController.approveVerification();
   183→    console.log("✅ Verification approved");
   184→  };
   185→
   186→  public static declineVerification = async () => {
   187→    if (!VerificationService.verificationController) {
   188→      throw new Error("Verification controller not initialized");
   189→    }
   190→    await VerificationService.verificationController.declineVerification();
   191→    console.log("❌ Verification declined");
   192→  };
   193→
   194→  public static cancelVerification = async () => {
   195→    if (!VerificationService.verificationController) {
   196→      throw new Error("Verification controller not initialized");
   197→    }
   198→    await VerificationService.verificationController.cancelVerification();
   199→    console.log("🚫 Verification cancelled");
   200→  };
   201→
   202→  public static startVerification = async () => {
   203→    if (!VerificationService.verificationController) {
   204→      throw new Error("Verification controller not initialized");
   205→    }
   206→    await VerificationService.verificationController.startSasVerification();
   207→    console.log("✅ Verification started");
   208→  };
   209→
   210→  public static hasDevicesToVerifyAgainst = async () => {
   211→    if (!MatrixCore.instance) return false;
   212→    return MatrixCore.instance.encryption().hasDevicesToVerifyAgainst();
   213→  };
   214→
   215→  public static requestDeviceVerification = async () => {
   216→    if (!VerificationService.verificationController) {
   217→      throw new Error("Verification controller not initialized");
   218→    }
   219→    await VerificationService.verificationController.requestDeviceVerification();
   220→    console.log("✅ Device verification requested");
   221→  };
   222→
   223→  public static verifyOtherUser = async (userId: string) => {
   224→    if (!VerificationService.verificationController) {
   225→      throw new Error("Verification controller not initialized");
   226→    }
   227→    await VerificationService.verificationController.requestUserVerification(userId);
   228→    console.log("✅ Verification requested");
   229→  };
   230→
   231→  public static isUserVerified = async (userId: string) => {
   232→    try {
   233→      const encryption = MatrixCore.getClient().encryption();
   234→      const userIdentity = await encryption.userIdentity(userId, true);
   235→      return !!userIdentity?.isVerified();
   236→    } catch (error) {
   237→      console.error("Failed to check user verification status:", error);
   238→      return false;
   239→    }
   240→  };
   241→}
