     1→import {
     2→  AuthData,
     3→  AuthDataPasswordDetails,
     4→  type BackupState,
     5→  CrossSigningResetAuthType_Tags,
     6→  type EnableRecoveryProgressListener,
     7→  type IdentityResetHandleInterface,
     8→  RecoveryState,
     9→  type TaskHandleInterface,
    10→} from "@unomed/react-native-matrix-sdk";
    11→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    12→import { mapBackupState } from "../../matrix-client/utils";
    13→
    14→export class EncryptionService {
    15→  public static setNewRecoveryKey = async () => {
    16→    return MatrixCore.getClient().encryption().resetRecoveryKey();
    17→  };
    18→
    19→  public static enableBackups = async () => {
    20→    await MatrixCore.getClient().encryption().enableBackups();
    21→  };
    22→
    23→  public static subscribeToBackupState = (
    24→    callback: (state: MappedBackupState) => void,
    25→  ): TaskHandleInterface => {
    26→    return MatrixCore.getClient()
    27→      .encryption()
    28→      .backupStateListener({
    29→        onUpdate: (state: BackupState) => {
    30→          callback(mapBackupState(state));
    31→        },
    32→      });
    33→  };
    34→
    35→  public static subscribeToRecoveryState = (
    36→    callback: (state: RecoveryState) => void,
    37→  ): TaskHandleInterface => {
    38→    return MatrixCore.getClient()
    39→      .encryption()
    40→      .recoveryStateListener({
    41→        onUpdate: (state: RecoveryState) => {
    42→          callback(state);
    43→        },
    44→      });
    45→  };
    46→
    47→  public static getBackupState = async (): Promise<MappedBackupState> => {
    48→    const client = MatrixCore.getClient();
    49→    await client.encryption().waitForE2eeInitializationTasks();
    50→    return mapBackupState(client.encryption().backupState());
    51→  };
    52→
    53→  public static getRecoveryState = async () => {
    54→    const client = MatrixCore.getClient();
    55→    await client.encryption().waitForE2eeInitializationTasks();
    56→    return client.encryption().recoveryState();
    57→  };
    58→
    59→  public static isRecoveryEnabled = async () => {
    60→    if (!MatrixCore.instance) return false;
    61→    const recoveryState = await EncryptionService.getRecoveryState();
    62→    return (
    63→      recoveryState === RecoveryState.Enabled ||
    64→      recoveryState === RecoveryState.Incomplete
    65→    );
    66→  };
    67→
    68→  public static enableRecovery = async (passphrase?: string) => {
    69→    const encryption = MatrixCore.getClient().encryption();
    70→
    71→    const progressListener: EnableRecoveryProgressListener = {
    72→      onUpdate: (status) => {
    73→        console.log("🔐 Recovery progress:", status);
    74→      },
    75→    };
    76→
    77→    const recoveryKey = await encryption.enableRecovery(
    78→      true,
    79→      passphrase,
    80→      progressListener,
    81→    );
    82→
    83→    await encryption.recover(recoveryKey);
    84→
    85→    console.log("✅ Recovery enabled! Save your recovery key securely.");
    86→    return recoveryKey;
    87→  };
    88→
    89→  public static resetRecoveryKey = async () => {
    90→    const encryption = MatrixCore.getClient().encryption();
    91→    const newRecoveryKey = await encryption.resetRecoveryKey();
    92→    await encryption.recover(newRecoveryKey);
    93→    console.log("✅ Recovery key reset! Save your new recovery key securely.");
    94→    return newRecoveryKey;
    95→  };
    96→
    97→  public static recoverWithKey = async (recoveryKey: string) => {
    98→    await MatrixCore.getClient().encryption().recover(recoveryKey);
    99→    console.log("✅ Successfully recovered using recovery key!");
   100→  };
   101→
   102→  public static disableRecovery = async () => {
   103→    await MatrixCore.getClient().encryption().disableRecovery();
   104→    console.log("⚠️ Recovery disabled");
   105→  };
   106→
   107→  /**
   108→   * Starts the identity reset process. Returns a handle if the server
   109→   * requires authentication (UIAA or OIDC), or undefined if the reset
   110→   * completed without auth. Must be followed by confirmIdentityReset().
   111→   */
   112→  public static startIdentityReset = async (): Promise<
   113→    IdentityResetHandleInterface | undefined
   114→  > => {
   115→    return MatrixCore.getClient().encryption().resetIdentity();
   116→  };
   117→
   118→  /**
   119→   * Completes the identity reset after user authentication.
   120→   * For UIAA: pass the user's password.
   121→   * For OIDC: call after the user has approved in the browser (no password needed).
   122→   */
   123→  public static confirmIdentityReset = async (
   124→    handle: IdentityResetHandleInterface,
   125→    password?: string,
   126→  ) => {
   127→    const authType = handle.authType();
   128→
   129→    if (authType.tag === CrossSigningResetAuthType_Tags.Uiaa) {
   130→      if (!password) throw new Error("Password required for identity reset");
   131→      const userId = MatrixCore.getClient().userId();
   132→      if (!userId) throw new Error("User ID not found");
   133→      const authData = new AuthData.Password({
   134→        passwordDetails: AuthDataPasswordDetails.create({
   135→          identifier: userId,
   136→          password,
   137→        }),
   138→      });
   139→      await handle.reset(authData);
   140→    } else {
   141→      // OIDC — user approved in browser
   142→      await handle.reset(undefined);
   143→    }
   144→  };
   145→
   146→  public static cancelIdentityReset = async (
   147→    handle: IdentityResetHandleInterface,
   148→  ) => {
   149→    await handle.cancel();
   150→  };
   151→}
   152→

