     1→import { useAtomValue, useSetAtom } from "jotai";
     2→import { NavigationContainerRef } from "modules/navigation/const";
     3→import { VerificationService } from "modules/verification/service/VerificationService";
     4→import { type FC, useEffect } from "react";
     5→import Toast from "react-native-toast-message";
     6→import { MatrixAtoms } from "../jotai";
     7→
     8→export const VerificationProvider: FC = () => {
     9→  const client = useAtomValue(MatrixAtoms.matrixClient);
    10→  const syncService = useAtomValue(MatrixAtoms.syncService);
    11→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    12→  const setVerificationEmojis = useSetAtom(MatrixAtoms.verificationEmojis);
    13→  const setVerificationSenderName = useSetAtom(
    14→    MatrixAtoms.verificationSenderName,
    15→  );
    16→
    17→  useEffect(() => {
    18→    if (!client || !syncService) return;
    19→
    20→    const setupVerificationListeners = async () => {
    21→      try {
    22→        const unsubscribe = await VerificationService.setupVerification(
    23→          // On verification request received
    24→          (details) => {
    25→            const senderName =
    26→              details.senderProfile.displayName || details.senderProfile.userId;
    27→            setVerificationSenderName(senderName);
    28→            setVerificationStatus("incomingRequest");
    29→
    30→            // Navigate to the VerifyUser screen
    31→            NavigationContainerRef.navigate("verifyUser", {
    32→              userId: details.senderProfile.userId,
    33→              flowId: details.flowId,
    34→            });
    35→          },
    36→          // On emojis received
    37→          (emojis) => {
    38→            setVerificationEmojis(emojis);
    39→            setVerificationStatus("emojis");
    40→          },
    41→          // On state change
    42→          (state) => {
    43→            console.log("Verification state changed:", state);
    44→
    45→            if (state === "success") {
    46→              setVerificationStatus("success");
    47→              setVerificationEmojis(null);
    48→              setVerificationSenderName(null);
    49→              Toast.show({
    50→                type: "success",
    51→                text1: "Device verified successfully!",
    52→              });
    53→            } else if (state === "failed") {
    54→              setVerificationStatus("failed");
    55→              setVerificationEmojis(null);
    56→              setVerificationSenderName(null);
    57→              Toast.show({
    58→                type: "error",
    59→                text1: "Verification failed",
    60→              });
    61→            } else if (state === "cancelled") {
    62→              setVerificationStatus("cancelled");
    63→              setVerificationEmojis(null);
    64→              setVerificationSenderName(null);
    65→              Toast.show({
    66→                type: "error",
    67→                text1: "Verification cancelled",
    68→              });
    69→            } else if (state === "emojis") {
    70→              setVerificationStatus("emojis");
    71→            } else if (state === "accepted") {
    72→              setVerificationStatus("accepted");
    73→            } else if (state === "sasStarted") {
    74→              setVerificationStatus("sasStarted");
    75→            }
    76→          },
    77→        );
    78→        return unsubscribe;
    79→      } catch (error) {
    80→        console.error("Failed to set up verification:", error);
    81→      } finally {
    82→        setVerificationStatus("idle");
    83→      }
    84→    };
    85→
    86→    setupVerificationListeners();
    87→  }, [client, syncService]);
    88→
    89→  return <></>;
    90→};
