    44→  const [uiaaHandle, setUiaaHandle] =
    45→    useState<IdentityResetHandleInterface | null>(null);
    46→  const [password, setPassword] = useState("");
    47→  // OIDC: handle kept in a ref (background task) + boolean to track waiting state
    48→  const oidcHandleRef = useRef<IdentityResetHandleInterface | null>(null);
    49→  const oidcCancelledRef = useRef(false);
    50→  const [isAwaitingOidc, setIsAwaitingOidc] = useState(false);
    51→  const [oidcUrl, setOidcUrl] = useState<string | null>(null);
    52→
