    54→  const setHasRunIdentityConfirmation = useSetAtom(
    55→    StorageAtoms.hasRunIdentityConfirmation,
    56→  );
    57→  const [_, setHasSeenProtectAccountMessage] = useMMKVBoolean(
    58→    SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE,
    59→  );
    60→
    61→  const finishReset = () => {
    62→    setHasRunIdentityConfirmation(true);
    63→    setHasSeenProtectAccountMessage(false);
