    89→        oidcHandleRef.current = handle;
    90→        setIsAwaitingOidc(true);
    91→        setOidcUrl(url);
    92→        setIsLoading(false);
    93→
    94→        const awaitOidcReset = async () => {
    95→          try {
    96→            await EncryptionService.confirmIdentityReset(handle);
    97→            oidcHandleRef.current = null;
    98→            setIsAwaitingOidc(false);
    99→            setOidcUrl(null);
   100→            if (!oidcCancelledRef.current) finishReset();
   101→          } catch (error) {
   102→            console.error(error);
   103→            oidcHandleRef.current = null;
   104→            setIsAwaitingOidc(false);
   105→            setOidcUrl(null);
   106→          }
   107→        };
