   113→        return;
   114→      }
   115→
   116→      // UIAA — show password input
   117→      setIsLoading(false);
   118→      setUiaaHandle(handle);
   119→    } catch (error) {
   120→      console.error(error);
   121→      Toast.show({
   122→        text1: "Failed to reset identity",
   123→        text2: "Please try again or contact support",
   124→        type: "error",
