    15→export const VerifyUser: FC<NativeStackScreenProps<Routes, "verifyUser">> = ({
    16→  route,
    17→  navigation,
    18→}) => {
    19→  const { userId, flowId } = route.params;
    20→  const [loading, setLoading] = useState(false);
    21→  const [verificationStatus, setVerificationStatus] = useAtom(
    22→    MatrixAtoms.verificationStatus,
    23→  );
    24→  const [userProfile, setUserProfile] = useState<UserProfile | undefined>(
    25→    undefined,
    26→  );
    27→  const isIncomingRequest = verificationStatus === "incomingRequest";
    28→  const isWaiting = verificationStatus === "waiting" || loading;
    29→  const isCancelled = verificationStatus === "cancelled";
    30→  const isAccepted = verificationStatus === "accepted";
    31→  const isSasStarted = verificationStatus === "sasStarted";
    32→  const isEmojis = verificationStatus === "emojis";
    33→
    34→  const getTitleText = () => {
    35→    if (isIncomingRequest) return "Verification request received";
