    94→      setLoading(true);
    95→      setVerificationStatus("waiting");
    96→      await VerificationService.acknowledgeVerification(userId, flowId);
    97→      await VerificationService.acceptVerificationRequest();
    98→      setVerificationStatus("accepted");
    99→    } catch (error) {
   100→      console.error(error);
